Here’s the **simplest** and **cleanest** code for **reverse a Singly Linked List** 👇  
(Just logic, no fancy stuff)

---

### ✅ C Code — Reverse SLL (Iterative easiest)

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

struct Node* reverse(struct Node* head) {
    struct Node *prev = NULL, *curr = head, *next = NULL;

    while (curr != NULL) {
        next = curr->next;  // save next
        curr->next = prev;  // reverse link
        prev = curr;        // move prev
        curr = next;        // move curr
    }
    return prev; // new head
}

// just for checking output
void printList(struct Node* head) {
    while (head != NULL) {
        printf("%d -> ", head->data);
        head = head->next;
    }
    printf("NULL\n");
}

// create node for testing
struct Node* newNode(int value) {
    struct Node* temp = (struct Node*)malloc(sizeof(struct Node));
    temp->data = value;
    temp->next = NULL;
    return temp;
}

int main() {
    struct Node* head = newNode(1);
    head->next = newNode(2);
    head->next->next = newNode(3);
    head->next->next->next = newNode(4);

    printf("Before Reverse: ");
    printList(head);

    head = reverse(head);

    printf("After Reverse: ");
    printList(head);

    return 0;
}
```

---

### 🧠 Logic (super short)
```
Take 3 pointers: prev, curr, next
Break current link → point it backward → move forward
```

